/** Original ordinary-alarm API using existing save/scheduling markers and exact content CAS. */
final class AlarmContentStore {
    private static final int MAX_JSON=131072,MAX_ALARMS=128;
    static String hash(String value){try{return NightAudioArchive.hash(MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException unavailable){throw new IllegalStateException("Alarm revision hashing is unavailable.");}}
    private static String raw(Store store,int id){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT CASE WHEN length(data)<=131072 THEN data ELSE NULL END FROM alarms WHERE id=?",new String[]{""+id})){if(!c.moveToFirst())return null;if(c.isNull(0))throw new IllegalArgumentException("This alarm is too large for the bounded API. Use SleepWell.");return c.getString(0);}}
    private static Alarm decode(String raw,int id){if(raw==null||raw.length()>MAX_JSON)throw new IllegalArgumentException("Alarm is absent or too large.");try{JSONObject json=new JSONObject(raw);if(SensorProvenance.whole(json,"id")!=id)throw new IllegalArgumentException("Alarm identity mismatch");for(String key:List.of("hour","minute"))SensorProvenance.whole(json,key);if(json.has("enabled")&&!(json.get("enabled") instanceof Boolean)||json.has("vibrate")&&!(json.get("vibrate") instanceof Boolean)||json.has("label")&&!(json.get("label") instanceof String))throw new IllegalArgumentException("Unsupported alarm field types");Alarm alarm=Alarm.read(json);if(alarm.hour<0||alarm.hour>23||alarm.minute<0||alarm.minute>59)throw new IllegalArgumentException("Invalid alarm clock");AlarmContentContract.mask(alarm);return alarm;}catch(JSONException invalid){throw new IllegalArgumentException("Alarm metadata needs review in SleepWell.");}}
    private static String revision(Context c,String raw,int id){SharedPreferences p=Prefs.of(c);return hash(raw+"\n"+p.getLong("deadline_"+id,0)+"\n"+p.getLong("lastOccurrence_"+id,0)+"\n"+AlarmAccessGrants.boot(c));}
    private static int count(Store store){try(Cursor c=store.getReadableDatabase().rawQuery("SELECT COUNT(*) FROM alarms",null)){return c.moveToFirst()?c.getInt(0):Integer.MAX_VALUE;}}
    private static String kind(Alarm a){return a.nap!=null||a.napInvalid?"nap":a.solar!=null||a.solarInvalid?"sunrise":a.date!=null||a.dateInvalid?"dated":a.repeatRule.custom()||a.repeatInvalid?"custom_repeat":a.nextOverride!=null||a.nextOverrideInvalid?"next_override":"clock";}
    private static String issue(Context c,Alarm a,String raw,int total){if(total>MAX_ALARMS)return "Alarm count exceeds this API’s bounded mutation scope.";if(AlarmService.active||Prefs.flag(c,"ringing"))return "An alarm is ringing. Finish it in SleepWell first.";if(!kind(a).equals("clock")||!a.weeklyNapOwner.isEmpty()||a.weeklyNapOwnerInvalid)return "This schedule/profile needs its dedicated SleepWell editor.";if(a.skip!=null||a.skipInvalid)return "Review or undo the skipped occurrence in SleepWell first.";if(!AlarmSkips.usable(a)||a.routineInvalid||a.soundModeInvalid||a.inputsInvalid||a.timingInvalid||a.bedtimeInvalid||a.snoozeTotalInvalid)return "Saved behavior needs review in SleepWell.";if(a.label==null||a.label.length()>80)return "This label exceeds the API’s bounded label scope.";try{new AlarmDefaults(a);JSONObject original=new JSONObject(raw),roundtrip=a.json();for(Iterator<String> keys=original.keys();keys.hasNext();)if(!preserved(original,roundtrip,keys.next()))return "Unsupported saved fields would not round-trip; use SleepWell.";}catch(JSONException|IllegalArgumentException invalid){return "Saved behavior is outside this API’s supported scope.";}SharedPreferences prefs=Prefs.of(c);if(prefs.getLong("snoozeBudget_"+a.id+"_pending",0)>0)return "This alarm has pending snooze ownership. Use SleepWell.";if(Prefs.number(c,"checkPending",0)==a.id)return "This alarm has a wake-up check owner. Use SleepWell.";WakeCheckState check;try{check=new WakeCheckStorage(prefs).load();}catch(RuntimeException unreadable){return "Wake-up check state needs review in SleepWell.";}if(check!=null&&check.alarmId==a.id)return "This alarm has a saved wake-up check owner. Use SleepWell.";if(check!=null&&!check.error.isEmpty())return "Wake-up check state needs review in SleepWell.";long next=prefs.getLong("deadline_"+a.id,0),now=System.currentTimeMillis();if(next>0&&next-now<=60000)return "The saved occurrence is due or within one minute. Use SleepWell.";return "";}
    static MatrixCursor read(Context c,AlarmContentContract.Request request,String[] projection,CancellationSignal signal,Runnable guard){MatrixCursor result=new MatrixCursor(projection,request.limit);int last=0;boolean more=false;try(Store store=Records.PRODUCTION.open(c)){SQLiteDatabase db=store.getReadableDatabase();db.beginTransactionNonExclusive();try{guard.run();String where="id>0 AND id<=2147483647";List<String> args=new ArrayList<>();if(request.id>0){where+=" AND id=?";args.add(""+request.id);}else if(request.before>0){where+=" AND id<CAST(? AS INTEGER)";args.add(""+request.before);}List<Integer> ids=new ArrayList<>();try(Cursor idsCursor=db.rawQuery("SELECT id FROM alarms WHERE "+where+" ORDER BY id DESC LIMIT "+(request.id>0?1:request.limit+1),args.toArray(new String[0]),signal)){while(idsCursor.moveToNext()){if(ids.size()==request.limit){more=true;break;}ids.add(idsCursor.getInt(0));}}int total=count(store);for(int id:ids){if(signal!=null)signal.throwIfCanceled();guard.run();last=id;Map<String,Object> row=new HashMap<>();row.put("_id",id);try{String saved=raw(store,id);Alarm alarm=decode(saved,id);String problem=issue(c,alarm,saved,total);row.put("revision",revision(c,saved,id));row.put("hour",alarm.hour);row.put("minute",alarm.minute);row.put("days_mask",AlarmContentContract.mask(alarm));row.put("label",alarm.label.length()<=80?alarm.label:null);row.put("enabled",alarm.enabled?1:0);row.put("vibrate",alarm.vibrate?1:0);row.put("kind",kind(alarm));row.put("writable",problem.isEmpty()?1:0);row.put("write_issue",problem.isEmpty()?null:problem);long deadline=Prefs.of(c).getLong("deadline_"+id,0);row.put("next_deadline_ms",alarm.enabled&&deadline>System.currentTimeMillis()?deadline:null);row.put("scheduling_status",alarm.scheduleError.isEmpty()?"no_saved_error":"needs_attention");}catch(RuntimeException unreadable){row.put("writable",0);row.put("write_issue","This saved alarm cannot be represented safely. Open SleepWell.");row.put("scheduling_status","unknown");}Object[] values=new Object[projection.length];for(int n=0;n<values.length;n++)values[n]=row.get(projection[n]);result.addRow(values);}guard.run();db.setTransactionSuccessful();}finally{db.endTransaction();}}Bundle extras=new Bundle();extras.putInt("contract_version",1);extras.putBoolean("has_more",more);if(more&&last>0)extras.putInt("next_before_id",last);extras.putString("order","_id DESC");result.setExtras(extras);guard.run();return result;}
    static int mutate(Context c,AlarmContentContract.Request request,ContentValues fields,AlarmAccessGrants.Admission caller,android.net.Uri uri){if(Records.factory!=Records.PRODUCTION)throw new IllegalStateException("The alarm runtime storage scope is unavailable.");synchronized(Scheduler.class){return AlarmAccessGrants.guarded(c,caller,uri,Intent.FLAG_GRANT_WRITE_URI_PERMISSION,()->{Runnable guard=()->AlarmAccessGrants.current(c,caller,uri,Intent.FLAG_GRANT_WRITE_URI_PERMISSION);guard.run();if(AlarmService.active||Prefs.flag(c,"ringing"))throw new IllegalStateException("Finish the ringing alarm before API edits.");String principal=caller.self?"internal":caller.uid+":"+caller.pkg+":"+AlarmAccessGrants.inspect(c,caller.pkg).signers;String payload=payload(request,fields);try(AlarmContentLedger ledger=new AlarmContentLedger(c);Store store=Records.PRODUCTION.open(c)){AlarmContentLedger.Receipt prior=ledger.find(principal,request.request,payload);if(prior!=null){if(prior.state.equals("prepared"))throw new IllegalStateException("This request was interrupted around alarm #"+prior.id+". Inspect Alarms; it is not automatically replayed.");AlarmAccessGrants.operationStatus(c,prior.status);return prior.id;}int total=count(store);if(total>MAX_ALARMS||request.operation.equals("insert")&&total>=MAX_ALARMS)throw new IllegalStateException("This API manages at most 128 saved alarms. Use SleepWell for a larger list.");Alarm original,draft;String saved=null;int id=request.id;
            if(request.operation.equals("insert")){int maximum;try(Cursor m=store.getReadableDatabase().rawQuery("SELECT COALESCE(MAX(id),0) FROM alarms",null)){maximum=m.moveToFirst()?m.getInt(0):Integer.MAX_VALUE;}maximum=Math.max(maximum,ledger.maximum());if(maximum==Integer.MAX_VALUE)throw new IllegalStateException("No alarm IDs remain.");id=maximum+1;SharedPreferences prefs=Prefs.of(c);int attempts=0;while(prefs.contains("deadline_"+id)||prefs.contains("snoozed_"+id)||Prefs.number(c,"checkPending",0)==id){if(++attempts>64||id==Integer.MAX_VALUE)throw new IllegalStateException("No safe unused alarm ID is available.");id++;}AlarmDefaultsSettings.Read defaults=AlarmDefaultsSettings.load(c);if(!defaults.error.isEmpty())throw new IllegalStateException("Saved alarm defaults need review in SleepWell.");draft=defaults.create(id);draft.enabled=false;original=Alarm.read(draft.json());AlarmContentContract.patch(draft,fields);String problem=issue(c,draft,draft.json().toString(),total);if(!problem.isEmpty())throw new IllegalArgumentException(problem);
            }else{saved=raw(store,id);original=decode(saved,id);if(!request.match.equals(revision(c,saved,id)))throw new IllegalStateException("Stale alarm revision. Query and review the latest alarm before writing.");String problem=issue(c,original,saved,total);if(!problem.isEmpty())throw new IllegalArgumentException(problem);draft=Alarm.read(original.json());if(!request.operation.equals("delete"))AlarmContentContract.patch(draft,fields);}
            if(!request.operation.equals("delete")){String problem=issue(c,draft,draft.json().toString(),total);if(!problem.isEmpty())throw new IllegalArgumentException(problem);if(draft.enabled){if(!AlarmScheduling.port.allowed(c))throw new IllegalStateException("Exact-alarm access is unavailable. Change it explicitly in SleepWell; no settings prompt was opened.");if(AlarmSkips.next(c,draft)<=System.currentTimeMillis()+60000)throw new IllegalArgumentException("Choose an occurrence more than one minute in the future.");}if(draft.challenges().randomCount==0&&draft.challenges().tasks.stream().anyMatch(task->task.type.equals("NFC"))&&Prefs.text(c,"nfcTag","").isEmpty())throw new IllegalArgumentException("Enroll the NFC tag in SleepWell before using this inherited challenge.");}
            guard.run();ledger.prepare(principal,request,payload,id);guard.run();String status;
            if(request.operation.equals("delete")){SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{guard.run();String actual=raw(store,id);if(actual==null||!request.match.equals(revision(c,actual,id))||!actual.equals(saved))throw new IllegalStateException("Alarm changed before deletion.");if(db.delete("alarms","id=? AND data=?",new String[]{""+id,saved})!=1)throw new IllegalStateException("Alarm deletion was not saved.");db.setTransactionSuccessful();}finally{db.endTransaction();}boolean cleaned=true;for(String action:new String[]{Scheduler.FIRE,Scheduler.SNOOZE,Scheduler.CHECK,Scheduler.BACKUP})try{Scheduler.cancel(c,id,action);}catch(RuntimeException uncertain){cleaned=false;}if(!Prefs.of(c).edit().putLong("deadline_"+id,0).commit())cleaned=false;HomeSurfaces.changed(c);status=cleaned?"Alarm #"+id+" deleted; own pending actions cancellation requested.":"Alarm #"+id+" deleted; pending-action cleanup needs attention. Open SleepWell.";
            }else{SQLiteDatabase db=store.getWritableDatabase();db.beginTransaction();try{guard.run();String actual=raw(store,id);boolean create=request.operation.equals("insert");if(create?actual!=null:actual==null||!actual.equals(saved)||!request.match.equals(revision(c,actual,id)))throw new IllegalStateException("Alarm changed before save.");NextAlarmOverrides.draft(c,draft,original);AlarmSkips.prepareEdit(store,draft,original,!create);draft.scheduleError="Saved. Alarm scheduling has not been confirmed. Retry to reconcile this alarm.";ContentValues row=new ContentValues();row.put("data",draft.json().toString());if(create){row.put("id",id);db.insertOrThrow("alarms",null,row);}else if(db.update("alarms",row,"id=? AND data=?",new String[]{""+id,saved})!=1)throw new IllegalStateException("The exact alarm snapshot changed before save.");AlarmSkips.verify(store,draft);db.setTransactionSuccessful();}finally{db.endTransaction();}HomeSurfaces.changed(c);try{Alarm updated=AlarmSkips.retry(c,draft);WakeChecks.alarmEdited(c,store,updated);status=updated.scheduleError.isEmpty()?"Alarm #"+id+" saved; scheduling call returned without a saved error.":"Alarm #"+id+" saved; scheduling needs attention. Open SleepWell.";}catch(RuntimeException uncertain){status="Alarm #"+id+" saved; scheduling is unconfirmed. Inspect and retry in SleepWell.";}}
            try{ledger.finish(principal,request.request,payload,request.operation.equals("delete")?"deleted":"saved",status);}catch(RuntimeException unconfirmed){status+=" Request receipt is unconfirmed; do not replay automatically.";}AlarmAccessGrants.operationStatus(c,status);return id;
        }});}}
    private static boolean preserved(JSONObject original,JSONObject roundtrip,String key)throws JSONException{if(!roundtrip.has(key))return false;Object before=original.get(key),after=roundtrip.get(key);if(key.equals("days")&&before instanceof JSONArray a&&after instanceof JSONArray b){if(a.length()!=b.length())return false;Set<Long> first=new HashSet<>(),second=new HashSet<>();for(int n=0;n<a.length();n++){first.add(HealthSleepCodec.whole(a,n));second.add(HealthSleepCodec.whole(b,n));}return first.size()==a.length()&&first.equals(second);}return same(before,after,0);}
    private static boolean same(Object a,Object b,int depth)throws JSONException{if(depth>24)return false;if(a==JSONObject.NULL||b==JSONObject.NULL)return a==b;if(a instanceof Number&&b instanceof Number)return Double.isFinite(((Number)a).doubleValue())&&Double.compare(((Number)a).doubleValue(),((Number)b).doubleValue())==0;if(a instanceof JSONObject x&&b instanceof JSONObject y){if(x.length()!=y.length())return false;for(Iterator<String> keys=x.keys();keys.hasNext();){String key=keys.next();if(!y.has(key)||!same(x.get(key),y.get(key),depth+1))return false;}return true;}if(a instanceof JSONArray x&&b instanceof JSONArray y){if(x.length()!=y.length())return false;for(int n=0;n<x.length();n++)if(!same(x.get(n),y.get(n),depth+1))return false;return true;}return a!=null&&a.equals(b);}
    private static String payload(AlarmContentContract.Request request,ContentValues fields){StringBuilder text=new StringBuilder(request.operation).append(':').append(request.id).append(':').append(request.match);if(fields!=null)for(String key:new TreeSet<>(fields.keySet()))text.append('\n').append(key).append('=').append(fields.get(key));return hash(text.toString());}
    private AlarmContentStore(){}
}
